ALTER TABLE "report_schedules" ADD CONSTRAINT "report_schedules_sections_unique" CHECK (array_position("report_schedules"."included_sections", null) is null and cardinality("report_schedules"."included_sections") = (case when 'summary'=any("report_schedules"."included_sections") then 1 else 0 end + case when 'revenue'=any("report_schedules"."included_sections") then 1 else 0 end + case when 'collections'=any("report_schedules"."included_sections") then 1 else 0 end + case when 'outstanding'=any("report_schedules"."included_sections") then 1 else 0 end + case when 'overdue'=any("report_schedules"."included_sections") then 1 else 0 end + case when 'payment_methods'=any("report_schedules"."included_sections") then 1 else 0 end + case when 'pending_cheques'=any("report_schedules"."included_sections") then 1 else 0 end + case when 'vat'=any("report_schedules"."included_sections") then 1 else 0 end + case when 'sales_by_client'=any("report_schedules"."included_sections") then 1 else 0 end + case when 'sales_by_product'=any("report_schedules"."included_sections") then 1 else 0 end + case when 'sales_by_category'=any("report_schedules"."included_sections") then 1 else 0 end + case when 'estimates'=any("report_schedules"."included_sections") then 1 else 0 end + case when 'deliveries'=any("report_schedules"."included_sections") then 1 else 0 end));--> statement-breakpoint
ALTER TABLE "report_schedules" ADD CONSTRAINT "report_schedules_cadence" CHECK (("report_schedules"."frequency"='daily' and "report_schedules"."weekday" is null and "report_schedules"."month_day" is null) or ("report_schedules"."frequency"='weekly' and "report_schedules"."weekday" is not null and "report_schedules"."weekday" between 1 and 7 and "report_schedules"."month_day" is null) or ("report_schedules"."frequency"='monthly' and "report_schedules"."weekday" is null and "report_schedules"."month_day" is not null and "report_schedules"."month_day" between 1 and 28));